47:     let pid = u64::from(std::process::id());
48:     let local = 0u64;
49:     let stack = (&local as *const u64) as u64;
50:     now ^ (pid << 32) ^ (stack >> 8)
51: }
52: 
53: /// Generate a random name not currently assigned to any robot.
54: ///
55: /// `avoid` is an extra name to reject (the robot's old name on reset),
56: /// so a reset always produces a name different from the previous one.
57: fn take_unused_name(avoid: Option<&str>) -> String {
58:     loop {
59:         let name = {
60:             let mut r = rng().lock().unwrap();
61:             format!(
62:                 "{}{}{:03}",
63:                 (b'A' + (r.next_u64() % 26) as u8) as char,
64:                 (b'A' + (r.next_u64() % 26) as u8) as char,
65:                 r.next_u64() % 1000,
66:             )
67:         };
68:         let mut used = USED_NAMES.lock().unwrap();
69:         if Some(name.as_str()) != avoid && used.insert(name.clone()) {
70:             return name;
71:         }
72:     }
73: }
74: 
75: pub struct Robot {
76:     name: String,
77: }
78: 
79: impl Robot {
80:     pub fn new() -> Self {
81:         Robot {
82:             name: take_unused_name(None),
83:         }
84:     }
85: 
86:     pub fn name(&self) -> &str {
87:         &self.name
88:     }
89: 
90:     pub fn reset_name(&mut self) {
91:         USED_NAMES.lock().unwrap().remove(&self.name);
92:         self.name = take_unused_name(Some(&self.name));
93:     }
94: }
